return (() => {
  // -----------------------------
  // 1. OBTENER TURNOS DE LOS TRES PILARES
  // -----------------------------
  const p1 = $('PILAR_1').first().json.turnosDisponibles || [];
  const p2 = $('PILAR_2').first().json.turnosDisponibles || [];
  const p3 = $('PILAR_3').first().json.turnosDisponibles || [];

  const allTurnos = [...p1, ...p2, ...p3];

  // -----------------------------
  // 2. FUNCIÓN PARA SELECCIONAR HASTA 16 TURNOS
  // -----------------------------
  function pick(arr) {
    const result = [];

    // Obtener días únicos
    const days = [...new Set(arr.map(t => t.dia))];

    // -----------------------------
    // PRIMERA PASADA:
    // → elegir como máximo 1 turno por día
    // -----------------------------
    while (result.length < 16 && days.length > 0) {
      // elegir un día al azar
      const d = days.splice(
        Math.floor(Math.random() * days.length),
        1
      )[0];

      // turnos disponibles ese día
      const options = arr.filter(t => t.dia === d);

      if (options.length > 0) {
        const chosen = options[Math.floor(Math.random() * options.length)];
        result.push(chosen);
      }
    }

    // -----------------------------
    // SEGUNDA PASADA:
    // → completar hasta 16 con cualquier turno restante
    // -----------------------------
    while (result.length < 16) {
      const remaining = arr.filter(
        t =>
          !result.some(
            r =>
              r.dia === t.dia &&
              r.horarioLlegada === t.horarioLlegada
          )
      );

      if (remaining.length === 0) break;

      const chosen =
        remaining[Math.floor(Math.random() * remaining.length)];
      result.push(chosen);
    }

    // -----------------------------
    // 3. FORMATO FINAL PARA EL AGENTE
    // -----------------------------
    return result.map(t => ({
      dia: t.dia,
      inicio: t.horarioLlegada,
      final: t.horarioEntrega,
      Id_Calendario: t.Id_Calendario,
      fechaFormato: t.fechaFormato
    }));
  }

  // -----------------------------
  // 4. RESPUESTA FINAL
  // -----------------------------
  return [
    {
      json: {
        turnos: pick(allTurnos)
      }
    }
  ];
})();

